WITH kept_keys AS (SELECT order_id FROM shipments EXCEPT ALL SELECT order_id FROM shipments WHERE cost <= 35), reconciled AS (SELECT s.* FROM shipments s INNER JOIN kept_keys k ON s.order_id = k.order_id) SELECT order_id, status, COUNT(CASE WHEN status = 'RETURNED' THEN 1 END) AS returned_count, STDDEV_SAMP(cost) AS cost_stddev, PERCENTILE_APPROX(cost, ARRAY(0.25, 0.5, 0.75)) AS cost_quartiles FROM reconciled GROUP BY order_id, status
